const fs = require('fs');
const path = require('path');

const filePath = path.resolve(__dirname, '..', '3d-globe.html');
let content = fs.readFileSync(filePath, 'utf-8');

function esc(s) { return (s || '').replace(/\\/g, '\\\\').replace(/'/g, "\\'").replace(/\n/g, '\\n').replace(/\r/g, '\\r').replace(/\t/g, '\\t'); }

function makeEntry(n, la, ln, sub, desc, fact) {
  return `  {n:'${esc(n)}',la:${la},ln:${ln},sub:'${esc(sub)}',desc:'${esc(desc)}',fact:'${esc(fact)}'},`;
}

function makeTrade(n, sub, desc, fact, pts) {
  const ptsStr = pts.map(p => `{la:${p[0]},ln:${p[1]}}`).join(',');
  return `  {n:'${esc(n)}',sub:'${esc(sub)}',desc:'${esc(desc)}',fact:'${esc(fact)}',pts:[${ptsStr}]},`;
}

function makeCurrent(n, temp, sub, desc, pts) {
  const ptsStr = pts.map(p => `{la:${p[0]},ln:${p[1]}}`).join(',');
  return `  {n:'${esc(n)}',temp:'${temp}',sub:'${esc(sub)}',desc:'${esc(desc)}',pts:[${ptsStr}]},`;
}

